/**
 ******************************************************************************
 * @file    tom_dac_output.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: adapted from Tom's own main.c (May 2026); most current lines are Brendon's RTOS port, tune and lockout glue (integrator, Sep-Oct 2026) and his output stage of 29-30 Oct 2026 (32/48 kHz playback and the crossover, written with an AI coding assistant); Tom's speaker balance trim is marked below.
 * @brief   I2S3 DAC output stage (Tom Gilbert) — PD6.
 *
 * What it does: TomTask is the toy's output stage. Every 4 ms it refills one
 * half of the DMA buffer that feeds the speakers through I2S3: Jack's
 * playback, a tune or beep, a test tone, or silence. No effect runs here any
 * more: effects are made ahead of time into effect files by FxRenderTask
 * (tom_fx_render.c). An effect file is 48 kHz, so it plays like any other
 * 48 kHz file (render_playback_half_48k, no upsampler), and playing an
 * effect costs no more CPU than playing the original recording.
 *
 * Words used here: I2S = a serial bus made for audio samples (here to the
 * DAC and amplifier that drive the speakers); DMA = a hardware unit that
 * copies the buffer to I2S3 by itself, so the CPU only has to refill it;
 * Q15 = a fraction stored as an integer times 32768 (32768 = 1.0); "slide N"
 * = the slide of ZEIT4230 lecture 07 whose pattern the code follows; PD6 =
 * the course's Prototype Design 6, this RTOS firmware; PD5b_Tom = the folder
 * of Tom's host-tested modules (Prototype Design 5b); PD2 = Prototype
 * Design 2, which holds the team's numbered system requirements (req 2.20).
 *
 * RTOS role: TomTask owns I2S3 (SPI3) + DMA1 Stream 5; blocks on
 * TOM_DAC_HALF_FLAG | TOM_DAC_FULL_FLAG | TOM_CMD_FLAG (osWaitForever);
 * consumes TomCmd_t from tomCmdQueue and AudioBlock_t* from audioBlockQueue
 * (frees them to audioBlockPool — consumer side of slide 31); acquires
 * faultBeepSem (slide 12); priority osPriorityAboveNormal; stack 1024 words.
 * Apart from that one wait it never blocks: every queue and semaphore call
 * here uses timeout 0, and freeing a pool block never waits. A wait could
 * make a half miss its 4 ms deadline. If the DMA will not start, TomTask
 * raises a fault (FAULT_AUDIO_SPK_START) for Tony's fault screen.
 *
 * Each released half (4 ms = 192 stereo frames), in order:
 *   1. the source:
 *      SOURCE_PLAYBACK, 32 kHz (recordings): two 64-sample blocks, each 2:3
 *                       upsampled (RateAdapter2to3) to 96 samples at 48 kHz
 *      SOURCE_PLAYBACK, 48 kHz (effect files, 48 kHz PC files): three
 *                       64-sample blocks, straight through; a block that does
 *                       not fit is kept (s_hold) and finished next half
 *                       (both: volume/mute gain, the same sample on L and R)
 *      SOURCE_TEST      the streaming test-pattern generator (phase-continuous)
 *      (none)           silence
 *      A tune replaces the source while it plays (tune_player.c, PD5b_Tom).
 *   2. the speaker crossover (crossover.c, PD5b_Tom): left = tweeter, what is
 *      above 1600 Hz; right = subwoofer, what is below 1600 Hz and above 10 Hz
 *   3. Tom's speaker balance trim, skipped on a silent half that the
 *      crossover bypassed (a trim of 0 is 0)
 *
 * Jack announces the rate of his blocks with TOM_CMD_SOURCE_PLAYBACK
 * (TomSourceRate_t, app_rtos.h); KEEP (0) keeps the rate set last.
 *
 * The circular DMA is started once at task start and never stopped: silence
 * is zeros, so there is never a click or a restart race.
 *
 * Tunes: the startup arpeggio once at task start, one fault beep per
 * faultBeepSem count, and TOM_CMD_PLAY_TUNE. Every tune (the startup sound
 * and the warning tunes) plays at a fixed 50 % amplitude, not scaled by the
 * UI volume or mute, and TOM_CMD_STOP does not cancel it. Only tunes of
 * priority >= TUNE_PRIORITY_FAULT (fault beep, critical battery) are warnings.
 *
 * Critical-battery lockout (TOM_CMD_BATTERY_LOCKOUT from BrendonTask, PD2 req
 * 2.20): engaging plays the critical tune and then holds the output at gain
 * 0 until the release. Meanwhile only warning tunes can be heard; the UI's
 * volume and mute are still stored and come back on the release. (PD2 req
 * 2.20: mute the speaker at critical charge.)
 *
 * CPU: one half is 288 000 cycles at the 72 MHz SYSCLK. This file and Tom's
 * DSP files are built at -O2 (root CMakeLists.txt): a half with sound takes
 * about 25-38 k cycles (9-13 %), a silent one about 1 k.
 ******************************************************************************/
#include "tom_dac_output.h"
#include "app_rtos.h"
#include "crossover.h"
#include "rate_adapter.h"
#include "tune_player.h"
#include <math.h>
#include <string.h>

#define PI_F 3.14159265359f

/* What feeds the speakers while no tune plays (a playing tune always wins):
 * nothing (silence), a test pattern, or Jack's playback blocks. */
typedef enum { SRC_NONE = 0, SRC_TEST, SRC_PLAYBACK } Source_t;

/* ----------------------------- private state ----------------------------- */
static I2S_HandleTypeDef *s_hi2s = NULL;
/* The DMA double buffer, written only by TomTask. The DMA sends it to I2S3
 * round and round (circular mode, 8 ms per lap). While it sends one half
 * (4 ms), TomTask refills the other: the half-way and end interrupts say
 * which half has just been sent and is free again. */
static int16_t  s_tx_buffer[TOM_BUFFER_SAMPLES];   /* [half 0 | half 1], L/R interleaved */
static uint8_t  s_dma_running = 0U;

static Source_t   s_source  = SRC_TEST;
static Tom_Test_t s_current = TOM_TEST_SILENT;
static uint8_t    s_volume  = TOM_VOLUME_DEFAULT;
static uint8_t    s_muted   = 0U;
static uint8_t    s_lockout = 0U;      /* critical-battery speaker lockout (TOM_CMD_BATTERY_LOCKOUT) */
static int32_t    s_gain_q15 = 0;      /* playback gain in Q15 (32768 = x1.0), set by update_gain() */

static int16_t    s_mono48[TOM_HALF_FRAMES];   /* one upsampled 32 kHz block (96 used), or a tune's half (192) */

/* Playback: the rate of Jack's blocks (TOM_CMD_SOURCE_PLAYBACK) */
static TomSourceRate_t s_rate = TOM_SRC_RATE_32K;  /* 32K: upsample 2:3; 48K: straight through (never KEEP) */
static RateAdapter2to3 s_upsampler;                /* the 2:3 upsampler's memory (32 kHz blocks) */

/* 48 kHz playback: the block being played when a half ended part-way
 * through it (Jack's short blocks at the end of a file and at every loop
 * point make blocks straddle halves). Owned by TomTask while held; freed to
 * audioBlockPool when used up, on a rate change and by drain_playback_queue(). */
static AudioBlock_t *s_hold = NULL;
static uint16_t      s_hold_played_samples = 0U;   /* samples of s_hold already played */

/* Speaker crossover: left = tweeter, right = subwoofer (crossover.c) */
static Crossover s_xover;

/* Streaming generator state */
static float    s_phase = 0.0f;           /* test tone phase (radians), carried from half to half: no click */

/* Tunes: startup sound and warnings (one player, only TomTask touches it) */
static tune_player_t s_tune;

/* Diagnostics (read through Tom_GetDeadlineMissed / Tom_GetUnderruns by
 * App_RTOS_GetStats: the debug screen's System page) */
static volatile uint32_t s_deadline_missed = 0U;
static volatile uint32_t s_underruns = 0U;

uint32_t Tom_GetDeadlineMissed(void) { return s_deadline_missed; }
uint32_t Tom_GetUnderruns(void)      { return s_underruns; }

/* The test patterns, in Tom_Test_t order: the tone's frequency (0 = not a
 * plain tone). */
typedef struct {
    Tom_Test_t  id;
    float       freq_hz;
} TestStep_t;

static const TestStep_t s_steps[TOM_TEST_COUNT] = {
    { TOM_TEST_SILENT,       0.0f },
    { TOM_TEST_SWEEP_100,  100.0f },
    { TOM_TEST_SWEEP_200,  200.0f },
    { TOM_TEST_SWEEP_500,  500.0f },
    { TOM_TEST_SWEEP_1K,  1000.0f },
    { TOM_TEST_SWEEP_2K,  2000.0f },
    { TOM_TEST_SWEEP_5K,  5000.0f },
    { TOM_TEST_SWEEP_8K,  8000.0f },
    { TOM_TEST_SWEEP_10K, 10000.0f },
    { TOM_TEST_LEFT_ONLY,  TOM_LR_TEST_HZ },
    { TOM_TEST_RIGHT_ONLY, TOM_LR_TEST_HZ },
};

/* TomTune_t (app_rtos.h, the TOM_CMD_PLAY_TUNE value) -> the const tunes in
 * tune_player.c. Pointers to const tables: flash only, no RAM. */
static const tune_t *const s_tunes[TOM_TUNE_COUNT] = {
    [TOM_TUNE_STARTUP]  = &g_tune_startup,
    [TOM_TUNE_CRITICAL] = &g_tune_critical,
    [TOM_TUNE_FAULT]    = &g_tune_fault,
};

/* --------------------------- gain ---------------------------------------- */
/* Playback gain (Q15): 0 while muted OR while the battery lockout holds.
 * s_volume and s_muted are kept either way, so a release restores exactly
 * what the UI last set, even if it changed during the lockout.
 * Q15: gain = volume x 32768 / 100, and apply_gain() multiplies a sample by
 * it and shifts right by 15 (divides by 32768). So 100 % leaves the sample
 * as it is and 50 % (16384) halves it (about -6 dB): integer maths only. */
static void update_gain(void)
{
    s_gain_q15 = (s_lockout || s_muted) ? 0 : (int32_t)((32768L * (int32_t)s_volume) / 100L);
}

/* --------------------------- half renderers ------------------------------ */
/* A steady tone for one half, on L and/or R. Phase accumulator: s_phase
 * grows by 2 pi f / fs per frame and carries on into the next half, so the
 * tone has no click at the half boundary; it is wrapped at 2 pi to keep the
 * float small and precise. */
static void render_sine_half(int16_t *dst, float freq_hz, int16_t amplitude,
                             uint8_t left_en, uint8_t right_en)
{
    const float phase_inc = 2.0f * PI_F * freq_hz / (float)TOM_AUDIO_FS;
    for (uint32_t frame = 0; frame < TOM_HALF_FRAMES; frame++) {
        int16_t sample = (int16_t)(amplitude * sinf(s_phase));
        dst[2U * frame]      = left_en  ? sample : 0;
        dst[2U * frame + 1U] = right_en ? sample : 0;
        s_phase += phase_inc;
        if (s_phase >= 2.0f * PI_F) s_phase -= 2.0f * PI_F;
    }
}

/* SRC_TEST: the selected test pattern (s_current), at a fixed amplitude
 * (not scaled by the volume). */
static void render_test_half(int16_t *dst)
{
    const TestStep_t *ts = &s_steps[s_current];
    switch (s_current) {
        case TOM_TEST_SILENT:     memset(dst, 0, TOM_HALF_SAMPLES * sizeof(int16_t)); break;
        case TOM_TEST_LEFT_ONLY:  render_sine_half(dst, TOM_LR_TEST_HZ, TOM_TEST_AMPLITUDE, 1U, 0U); break;
        case TOM_TEST_RIGHT_ONLY: render_sine_half(dst, TOM_LR_TEST_HZ, TOM_TEST_AMPLITUDE, 0U, 1U); break;
        default:                  render_sine_half(dst, ts->freq_hz, TOM_TEST_AMPLITUDE, 1U, 1U); break;
    }
}

/* A tune replaces the source for the whole half, as the fault beep did: the
 * same mono samples on L and R, fixed amplitude (no volume, no mute). If the
 * tune ends inside this half, the rest of the half is silence; the next half
 * plays the queued tune if there is one, otherwise the source.
 * During the battery lockout a tune that is not a warning plays out in
 * silence. Engaging the lockout already cuts the startup sound and PLAY_TUNE
 * refuses one, so this only catches a non-warning tune that was queued
 * behind a warning before the lockout began. */
static void render_tune_half(int16_t *dst)
{
    const tune_t *t = tune_player_current(&s_tune);   /* the tune this half belongs to */
    const uint8_t silent = (s_lockout && t != NULL && t->priority < TUNE_PRIORITY_FAULT) ? 1U : 0U;
    (void)tune_player_render(&s_tune, s_mono48, TOM_HALF_FRAMES);
    for (uint32_t frame = 0; frame < TOM_HALF_FRAMES; frame++) {
        const int16_t v = silent ? 0 : s_mono48[frame];
        dst[2U * frame]      = v;
        dst[2U * frame + 1U] = v;
    }
}

/* Volume and mute: the Q15 playback gain, clipped to int16. */
static int16_t apply_gain(int16_t sample)
{
    int32_t y = ((int32_t)sample * s_gain_q15) >> 15;
    if (y > 32767) {
        y = 32767;
    } else if (y < -32768) {
        y = -32768;
    }
    return (int16_t)y;
}

/* The same mono sample on both channels of frame f (L first, then R). */
static void put_mono_frame(int16_t *dst, uint32_t f, int16_t sample)
{
    dst[2U * f]      = sample;
    dst[2U * f + 1U] = sample;
}

/* Silence from frame `frames` to the end of the half: Jack's next block is
 * late (an underrun, counted for the debug screen). */
static void silence_rest_of_half(int16_t *dst, uint32_t frames)
{
    memset(&dst[2U * frames], 0, (TOM_HALF_FRAMES - frames) * 2U * sizeof(int16_t));
    s_underruns++;
}

/* One 32 kHz block -> frames in dst: upsample 2:3 -> gain -> L/R. */
static uint32_t render_block_frames(int16_t *dst, const int16_t *in, uint32_t n)
{
    uint32_t m = RateAdapter2to3_Process(&s_upsampler, in, n, s_mono48);
    for (uint32_t j = 0; j < m; j++) {
        put_mono_frame(dst, j, apply_gain(s_mono48[j]));
    }
    return m;
}

/* 32 kHz playback (recordings): two 64-sample blocks per half (2 x 96 =
 * 192 frames). Consumer side of the pool + pointer queue (slide 31): get ->
 * process -> free. After a short block (the end of the file, so once per
 * loop) the blocks no longer line up with the half: a block that does not
 * fit in what is left plays only what fits, and the rest of it is dropped,
 * as before. That is at most 126 samples (about 4 ms) per loop, next to the
 * loop's own jump; a recording (whole 1 ms frames) loses 1 ms or nothing. */
static void render_playback_half_32k(int16_t *dst)
{
    uint32_t frames = 0U;
    while (frames < TOM_HALF_FRAMES) {
        AudioBlock_t *blk = NULL;
        if (osMessageQueueGet(audioBlockQueue, &blk, NULL, 0U) != osOK || blk == NULL) {
            silence_rest_of_half(dst, frames);
            return;
        }
        uint32_t n = blk->count;
        if (n > AUDIO_BLOCK_SAMPLES) n = AUDIO_BLOCK_SAMPLES;
        if (n > 0U) {
            /* Only what fits in the rest of this half; never 0 (rate_adapter.h). */
            n = RateAdapter2to3_InputThatFits(n, TOM_HALF_FRAMES - frames);
            frames += render_block_frames(&dst[2U * frames], blk->pcm, n);
        }
        (void)osMemoryPoolFree(audioBlockPool, blk);
    }
}

/* Give the held 48 kHz block back to audioBlockPool (used up, or stopped). */
static void release_held_block(void)
{
    if (s_hold == NULL) return;
    (void)osMemoryPoolFree(audioBlockPool, s_hold);
    s_hold = NULL;
    s_hold_played_samples = 0U;
}

/* Hold Jack's next 48 kHz block; 0 when none is queued yet. */
static uint8_t hold_next_block(void)
{
    AudioBlock_t *blk = NULL;
    if (osMessageQueueGet(audioBlockQueue, &blk, NULL, 0U) != osOK || blk == NULL) return 0U;
    s_hold = blk;
    s_hold_played_samples = 0U;
    return 1U;
}

/* 48 kHz playback (effect files, 48 kHz PC files): three 64-sample blocks
 * per half (3 x 64 = 192 frames), no upsampler. Unlike the 32 kHz path no
 * sample is ever dropped: after a short block (the end of a file, every
 * loop point) the next block straddles two halves, so the block being
 * played stays in s_hold (s_hold_played_samples of it are played), and
 * the next half carries on from there. */
static void render_playback_half_48k(int16_t *dst)
{
    uint32_t frames = 0U;
    while (frames < TOM_HALF_FRAMES) {
        if (s_hold == NULL) {
            if (!hold_next_block()) {           /* Jack's next block is late */
                silence_rest_of_half(dst, frames);
                return;
            }
        }
        uint32_t n = s_hold->count;
        if (n > AUDIO_BLOCK_SAMPLES) n = AUDIO_BLOCK_SAMPLES;
        uint32_t take = n - s_hold_played_samples;      /* samples of the block not played yet */
        if (take > TOM_HALF_FRAMES - frames) take = TOM_HALF_FRAMES - frames;
        for (uint32_t j = 0; j < take; j++) {
            put_mono_frame(dst, frames + j, apply_gain(s_hold->pcm[s_hold_played_samples + j]));
        }
        frames += take;
        s_hold_played_samples = (uint16_t)(s_hold_played_samples + take);
        if (s_hold_played_samples >= n) release_held_block();   /* used up (also an empty block) */
    }
}

static void render_playback_half(int16_t *dst)
{
    if (s_rate == TOM_SRC_RATE_48K) {
        render_playback_half_48k(dst);
    } else {
        render_playback_half_32k(dst);
    }
}

/* Refill one half of s_tx_buffer (half 0 or 1): the source (a playing tune
 * comes first), then the crossover and the trim. The DMA is sending the
 * other half meanwhile, so this has 4 ms to finish. */
static void render_half(uint32_t half)
{
    int16_t *dst = &s_tx_buffer[half * TOM_HALF_SAMPLES];

    if (tune_player_busy(&s_tune)) {
        render_tune_half(dst);
    }
    else {
        switch (s_source) {
            case SRC_TEST:
                /* Test patterns are not gain-scaled, so the battery lockout
                 * silences them here. */
                if (s_lockout) {
                    memset(dst, 0, TOM_HALF_SAMPLES * sizeof(int16_t));
                } else {
                    render_test_half(dst);
                }
                break;

            case SRC_PLAYBACK:
                render_playback_half(dst);
                break;

            default:
                memset(dst, 0, TOM_HALF_SAMPLES * sizeof(int16_t));
                break;
        }
    }

    /* Speaker crossover (crossover.c), on every half whatever its source:
     * the left channel (tweeter) keeps what is above 1600 Hz, the right
     * (subwoofer) what is below it and above 10 Hz. It filters each channel,
     * so the left-only and right-only test patterns are filtered too. On a
     * silent half whose filters have rung down it does nothing and returns
     * true: the half is all zeros and a trim of 0 is 0, so the trim below is
     * skipped as well. That keeps TomTask near 1 % of the CPU while nothing
     * plays, which leaves the CPU to FxRenderTask making effect files. */
    if (Crossover_ProcessInterleaved(&s_xover, dst, TOM_HALF_FRAMES)) {
        return;
    }

    /* TEAM CODE (written by Tom, 28 Sep 2026): left/right speaker balance trim on every half buffer */
    /*
     * Apply final left/right speaker balance trim.
     *
     * I2S stereo buffer is interleaved:
     *   dst[0] = Left
     *   dst[1] = Right
     *   dst[2] = Left
     *   dst[3] = Right
     *   ...
     *
     * Applying trim here ensures EVERY audio source is affected:
     * test tones, left/right tests, playback and tunes (fault beep included).
     */
    for (uint32_t frame = 0U; frame < TOM_HALF_FRAMES; frame++) {

        dst[2U * frame] =
            Tom_ApplySpeakerTrim(
                dst[2U * frame],
                TOM_LEFT_TRIM_PERCENT
            );

        dst[2U * frame + 1U] =
            Tom_ApplySpeakerTrim(
                dst[2U * frame + 1U],
                TOM_RIGHT_TRIM_PERCENT
            );
    }
}

/* --------------------------- DMA control --------------------------------- */
/* Start the DMA once. The size counts 16-bit samples: TOM_BUFFER_SAMPLES
 * (768) is both halves. The stream is circular (set in main.c), so after
 * the last sample it starts again at the first, for ever. main.c's
 * HAL_I2S_TxHalfCpltCallback / HAL_I2S_TxCpltCallback (interrupts, at the
 * half-way point and at the end) only set TOM_DAC_HALF_FLAG /
 * TOM_DAC_FULL_FLAG for this task: the refilling is done here, in the task.
 * If the DMA will not start, no half is ever released and the speakers stay
 * silent, so the fault screen says so (once: this runs once, at task start). */
static void start_dma(void)
{
    if (s_dma_running) return;
    if (HAL_I2S_Transmit_DMA(s_hi2s, (uint16_t *)s_tx_buffer, TOM_BUFFER_SAMPLES) != HAL_OK) {
        App_RTOS_RaiseFault((uint8_t)FAULT_SRC_AUDIO, (uint8_t)FAULT_AUDIO_SPK_START,
                            "Speaker DMA failed", "No sound");
        return;
    }
    s_dma_running = 1U;
}

/* Drop the playback: every queued block, and the 48 kHz block held over
 * from the last half (s_hold). Runs on STOP, SOURCE_TEST and TEST_PATTERN.
 * The held block counts too: without freeing it the 16-block pool would
 * lose one block at every stop, and after 16 stops playback would stall. */
static void drain_playback_queue(void)
{
    AudioBlock_t *blk = NULL;
    release_held_block();
    while (osMessageQueueGet(audioBlockQueue, &blk, NULL, 0U) == osOK) {
        if (blk != NULL) (void)osMemoryPoolFree(audioBlockPool, blk);
    }
}

/* --------------------------- commands ------------------------------------ */
/* TOM_CMD_TEST_PATTERN (Tony's debug Speaker page): select a pattern and
 * make the test generator the source, from phase 0. */
static void apply_test(Tom_Test_t step)
{
    if (step >= TOM_TEST_COUNT) return;
    s_current = step;
    s_phase = 0.0f;
    s_source = SRC_TEST;
}

/* TOM_CMD_SOURCE_PLAYBACK: play Jack's blocks from now on, at the rate he
 * announces (TomSourceRate_t). KEEP keeps the rate set last, for a sender
 * that does not know it, and an unknown value keeps it too (Tony's debug
 * screen after a test pattern). A rate change frees a held 48 kHz block: it
 * belongs to the old stream. */
static void select_playback(uint8_t value)
{
    TomSourceRate_t rate = s_rate;
    if (value == (uint8_t)TOM_SRC_RATE_32K || value == (uint8_t)TOM_SRC_RATE_48K) {
        rate = (TomSourceRate_t)value;
    }
    if (rate != s_rate) {
        release_held_block();
        s_rate = rate;
    }
    s_source = SRC_PLAYBACK;
    RateAdapter2to3_Reset(&s_upsampler);   /* a new start: no step from the last sound */
}

/* TOM_CMD_PLAY_TUNE. A request while another tune plays is queued once
 * (tune_player_request); a tune already playing or queued, or outranked by
 * the one playing, is ignored. An unknown tune number is ignored too. */
static void play_tune(uint8_t id)
{
    if (id >= TOM_TUNE_COUNT) return;
    const tune_t *t = s_tunes[id];
    if (s_lockout && t->priority < TUNE_PRIORITY_FAULT) {
        return;     /* battery lockout: only warnings may sound (the startup tune is not one) */
    }
    (void)tune_player_request(&s_tune, t);
}

/* TOM_CMD_BATTERY_LOCKOUT (critical battery, PD2 req 2.20).
 * Engage: a playing tune that is not a warning (the startup sound) is cut
 * short, the 520 ms critical tune is played (or queued behind a warning that
 * is already playing), then the output gain is held at 0. Tunes are not
 * gain-scaled, so the critical tune and any later fault beep still sound;
 * playback keeps running in silence (Jack's blocks are still consumed) and
 * test patterns render silence. Release: the stored volume and mute apply
 * again. BrendonTask repeats its current state (engage or release) about
 * every 10 s, so a command that matches the current state changes nothing
 * (and does not play the critical tune again). */
static void battery_lockout(uint8_t engage)
{
    if (engage && !s_lockout) {
        const tune_t *cur = tune_player_current(&s_tune);
        if (cur != NULL && cur->priority < TUNE_PRIORITY_FAULT) {
            tune_player_stop(&s_tune);
        }
        (void)tune_player_request(&s_tune, &g_tune_critical);
        s_lockout = 1U;
        update_gain();
    } else if (!engage && s_lockout) {
        s_lockout = 0U;
        update_gain();
    }
}

/* One TomCmd_t from tomCmdQueue (sent by TonyTask, BrendonTask or
 * JackStorageTask; the types are listed in app_rtos.h). TOM_CMD_SET_EFFECT
 * is obsolete (effects are made ahead of time into effect files by
 * FxRenderTask), so like any unknown type it falls to default and is
 * ignored. */
static void handle_cmd(const TomCmd_t *c)
{
    switch (c->type) {
        case TOM_CMD_SET_VOLUME:
            s_volume = (c->value > 100U) ? 100U : c->value;
            update_gain();
            break;
        case TOM_CMD_SET_MUTE:
            s_muted = c->value ? 1U : 0U;
            update_gain();
            break;
        case TOM_CMD_SOURCE_PLAYBACK:
            select_playback(c->value);
            break;
        case TOM_CMD_SOURCE_TEST:
            drain_playback_queue();
            s_source = SRC_TEST;
            break;
        case TOM_CMD_TEST_PATTERN:
            drain_playback_queue();
            apply_test((Tom_Test_t)c->value);
            break;
        case TOM_CMD_STOP:
            /* Stops the source only. A playing tune carries on: tunes do
             * not depend on the source. */
            drain_playback_queue();
            s_source = SRC_NONE;
            break;
        case TOM_CMD_PLAY_TUNE:
            play_tune(c->value);
            break;
        case TOM_CMD_BATTERY_LOCKOUT:
            battery_lockout(c->value);
            break;
        default: break;
    }
}

/* --------------------------------- API ----------------------------------- */
void Tom_Init(I2S_HandleTypeDef *hi2s)
{
    s_hi2s = hi2s;
    s_current = TOM_TEST_SILENT;
    s_source = SRC_TEST;
    memset(s_tx_buffer, 0, sizeof(s_tx_buffer));
    update_gain();
    RateAdapter2to3_Reset(&s_upsampler);            /* pure C, no RTOS object */
    Crossover_Init(&s_xover, (float)TOM_AUDIO_FS);  /* pure C: the 1600 Hz and 10 Hz filters */
    tune_player_init(&s_tune, TOM_AUDIO_FS);   /* pure C, idle */
    /* The DMA is started by Tom_TaskEntry, once, and never stopped. */
}

/* --------------------------------- task ---------------------------------- */
void Tom_TaskEntry(void *argument)
{
    (void)argument;
    start_dma();
    /* Startup sound: the DMA is running and no playback source has been
     * selected yet. Nothing waits for it: Tom renders it half by half like any
     * other source, while TonyTask draws the home menu. */
    if (s_dma_running) {
        (void)tune_player_request(&s_tune, &g_tune_startup);
    }

    for (;;) {
        /* Sleep until a DMA interrupt says a half is free (every 4 ms while
         * the DMA runs) or a command arrives; any one of the three flags
         * wakes the task, and the call clears the flags it returns. */
        uint32_t flags = osThreadFlagsWait(TOM_DAC_HALF_FLAG | TOM_DAC_FULL_FLAG | TOM_CMD_FLAG,
                                           osFlagsWaitAny, osWaitForever);
        if ((flags & osFlagsError) != 0U) continue;     /* an error code, not flags */

        /* Every queued command: the flag is a single bit, so one wake-up can
         * stand for several puts. */
        if (flags & TOM_CMD_FLAG) {
            TomCmd_t c;
            while (osMessageQueueGet(tomCmdQueue, &c, NULL, 0U) == osOK) handle_cmd(&c);
        }
        /* One fault beep per faultBeepSem count. The semaphore is only taken
         * while no tune plays, so a backlog plays as one beep after another
         * and a beep never cuts another tune short. */
        if (!tune_player_busy(&s_tune) && osSemaphoreAcquire(faultBeepSem, 0U) == osOK) {
            (void)tune_player_request(&s_tune, &g_tune_fault);
        }
        /* Both halves free at once: the task is late by a whole half, so the
         * DMA has already started sending a half that was not refilled in
         * time (old sound goes out). Counted, not hidden (slide 9). */
        if ((flags & (TOM_DAC_HALF_FLAG | TOM_DAC_FULL_FLAG)) == (TOM_DAC_HALF_FLAG | TOM_DAC_FULL_FLAG)) {
            s_deadline_missed++;          /* slide 9 */
        }
        /* HALF: the DMA has just sent half 0 and is now sending half 1, so
         * refill half 0. FULL: it has sent half 1 and wrapped round to half 0,
         * so refill half 1. */
        if (flags & TOM_DAC_HALF_FLAG) render_half(0U);
        if (flags & TOM_DAC_FULL_FLAG) render_half(1U);
    }
}
